package com.marketplace.productservice;
import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI;
@RestController @RequestMapping("/api/products") @Tag(name="Produtos") class ProductController {private final ProductService service;ProductController(ProductService s){service=s;}@GetMapping @Operation(summary="Pesquisa produtos com filtros, paginação e ordenação") Page<ProductDtos.Response> search(@RequestParam(required=false) String q,@PageableDefault(size=20,sort="name") Pageable pageable){return service.search(q,pageable);}@GetMapping("/{id}") ProductDtos.Response get(@PathVariable Long id){return service.get(id);}@PostMapping ResponseEntity<ProductDtos.Response> create(@Valid @RequestBody ProductDtos.Request r){var p=service.create(r);return ResponseEntity.created(URI.create("/api/products/"+p.id())).body(p);}@PutMapping("/{id}") ProductDtos.Response update(@PathVariable Long id,@Valid @RequestBody ProductDtos.Request r){return service.update(id,r);}@PostMapping("/{id}/reservations") ProductDtos.Response reserve(@PathVariable Long id,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody ProductDtos.ReservationRequest r){return service.reserve(id,r,key);}}
